    "content_html": "<ul>\r\n<li><p><span class=\"math inline\">\\(\\overline{A * B}\\)</span> = <span\r\nclass=\"math inline\">\\(\\overline{A}\\)</span> + <span\r\nclass=\"math inline\">\\(\\overline{B}\\)</span></p></li>\r\n<li><p><span class=\"math inline\">\\(\\overline{A + B}\\)</span> = <span\r\nclass=\"math inline\">\\(\\overline{A}\\)</span> * <span\r\nclass=\"math inline\">\\(\\overline{B}\\)</span></p></li>\r\n</ul>",
